-- Mentora — full schema for MySQL Workbench's "Reverse Engineer SQL Script"
-- (Database > Reverse Engineer... > choose "SQL Script" as the source, point
-- it at this file). Generated by hand from backend/database/models.py
-- (SQLAlchemy ORM) — the real app runs on SQLite for development, but this
-- file is written in plain MySQL DDL purely so Workbench can draw a clean
-- EER diagram from it. 17 tables, in FK-safe creation order (every table a
-- FOREIGN KEY points at is created before the table that references it).

SET FOREIGN_KEY_CHECKS = 0;

-- ============================================================
-- Core
-- ============================================================

CREATE TABLE users (
    user_id             INT AUTO_INCREMENT PRIMARY KEY,
    first_name          VARCHAR(80)  NOT NULL,
    last_name           VARCHAR(80)  NOT NULL,
    email               VARCHAR(255) NOT NULL UNIQUE,
    password_hash       VARCHAR(255) NOT NULL,
    university          VARCHAR(255) NOT NULL,
    exam_goal           VARCHAR(50)  NOT NULL,
    created_at          DATETIME     NOT NULL,
    reset_code          VARCHAR(6)   NULL,
    reset_code_expires_at DATETIME   NULL,
    notification_prefs  JSON         NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE student_intelligence_profile (
    sip_id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id             INT NOT NULL UNIQUE,
    skill_vector        JSON NULL,
    career_rankings     JSON NULL,
    priority_queue      JSON NULL,
    roadmap             JSON NULL,
    updated_at          DATETIME NOT NULL,
    CONSTRAINT fk_sip_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Exam Prep
-- ============================================================

CREATE TABLE exam_sessions (
    session_id          INT AUTO_INCREMENT PRIMARY KEY,
    user_id             INT NOT NULL,
    exam_type           VARCHAR(50)  NOT NULL,
    subject             VARCHAR(100) NOT NULL,
    start_time          DATETIME NOT NULL,
    end_time            DATETIME NULL,
    total_score         FLOAT NULL,
    CONSTRAINT fk_examsession_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE questions (
    question_id          INT AUTO_INCREMENT PRIMARY KEY,
    subject               VARCHAR(100) NOT NULL,
    topic                  VARCHAR(150) NOT NULL,
    subtopic               VARCHAR(150) NULL,
    difficulty             VARCHAR(20)  NOT NULL,
    question_text          TEXT         NOT NULL,
    options                 JSON         NOT NULL,
    correct_answer          VARCHAR(10)  NOT NULL,
    source                   VARCHAR(255) NULL,
    correct_answer_source     VARCHAR(20)  NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE session_answers (
    answer_id            INT AUTO_INCREMENT PRIMARY KEY,
    session_id           INT NOT NULL,
    question_id          INT NOT NULL,
    student_answer       VARCHAR(10) NOT NULL,
    is_correct           BOOLEAN NOT NULL DEFAULT FALSE,
    time_taken_sec       INT NULL,
    CONSTRAINT fk_sessionanswer_session FOREIGN KEY (session_id) REFERENCES exam_sessions(session_id),
    CONSTRAINT fk_sessionanswer_question FOREIGN KEY (question_id) REFERENCES questions(question_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE topic_scores (
    topic_score_id       INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    subject              VARCHAR(100) NOT NULL,
    topic                VARCHAR(150) NOT NULL,
    score                FLOAT NOT NULL,
    last_updated         DATETIME NOT NULL,
    CONSTRAINT fk_topicscore_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Shared, app-wide curated videos per topic — not owned by any one user
-- (see TopicVideo's own comment in models.py: no admin-role concept exists
-- yet, so any logged-in account can edit this table via /admin).
CREATE TABLE topic_videos (
    topic                VARCHAR(150) PRIMARY KEY,
    video_url            VARCHAR(500) NOT NULL,
    title                VARCHAR(255) NOT NULL,
    updated_at           DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Career Counseling
-- ============================================================

CREATE TABLE career_profiles (
    career_id            INT AUTO_INCREMENT PRIMARY KEY,
    title                VARCHAR(150) NOT NULL,
    description          TEXT NULL,
    required_skills      JSON NULL,
    onet_code            VARCHAR(20) NULL,
    category             VARCHAR(100) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE career_rankings (
    ranking_id           INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    career_id            INT NOT NULL,
    match_score          FLOAT NOT NULL,
    key_skill_gap        VARCHAR(255) NULL,
    ranked_at            DATETIME NOT NULL,
    CONSTRAINT fk_careerranking_user FOREIGN KEY (user_id) REFERENCES users(user_id),
    CONSTRAINT fk_careerranking_career FOREIGN KEY (career_id) REFERENCES career_profiles(career_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE roadmaps (
    roadmap_id           INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    career_id            INT NOT NULL,
    month_number         VARCHAR(10) NOT NULL,
    milestone_title      VARCHAR(255) NOT NULL,
    description          TEXT NULL,
    status               VARCHAR(20) NOT NULL DEFAULT 'pending',
    explanation          TEXT NULL,
    CONSTRAINT fk_roadmap_user FOREIGN KEY (user_id) REFERENCES users(user_id),
    CONSTRAINT fk_roadmap_career FOREIGN KEY (career_id) REFERENCES career_profiles(career_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE cv_uploads (
    cv_id                INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    file_path            VARCHAR(500) NOT NULL,
    uploaded_at          DATETIME NOT NULL,
    extracted_skills     JSON NULL,
    gpa                  FLOAT NULL,
    certifications       JSON NULL,
    projects             JSON NULL,
    CONSTRAINT fk_cvupload_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Mock Interview
-- ============================================================

CREATE TABLE interview_sessions (
    interview_id         INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    career_id            INT NULL,
    started_at           DATETIME NOT NULL,
    ended_at             DATETIME NULL,
    CONSTRAINT fk_interviewsession_user FOREIGN KEY (user_id) REFERENCES users(user_id),
    CONSTRAINT fk_interviewsession_career FOREIGN KEY (career_id) REFERENCES career_profiles(career_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE interview_qa (
    qa_id                INT AUTO_INCREMENT PRIMARY KEY,
    interview_id         INT NOT NULL,
    question_text        TEXT NOT NULL,
    student_answer       TEXT NULL,
    ai_feedback          TEXT NULL,
    CONSTRAINT fk_interviewqa_session FOREIGN KEY (interview_id) REFERENCES interview_sessions(interview_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Learning Portal
-- ============================================================

CREATE TABLE playlist_items (
    item_id              INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    title                VARCHAR(255) NOT NULL,
    subject              VARCHAR(100) NOT NULL,
    source               VARCHAR(150) NOT NULL,
    duration_min         INT NOT NULL,
    note                 VARCHAR(255) NOT NULL,
    video_url            VARCHAR(500) NOT NULL,
    added_at             DATETIME NOT NULL,
    CONSTRAINT fk_playlistitem_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE watch_history (
    watch_id             INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    title                VARCHAR(255) NOT NULL,
    subject              VARCHAR(100) NOT NULL,
    watched_at           DATETIME NOT NULL,
    CONSTRAINT fk_watchhistory_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- owner_user_id NULL = a shared catalog resource visible to every student
-- (e.g. board past papers); set = a private self-upload visible only to
-- its owner. See Material's own comment in models.py.
CREATE TABLE materials (
    material_id          INT AUTO_INCREMENT PRIMARY KEY,
    owner_user_id        INT NULL,
    title                VARCHAR(255) NOT NULL,
    size_label           VARCHAR(50) NOT NULL,
    source               VARCHAR(150) NOT NULL,
    uploaded_at          DATETIME NOT NULL,
    CONSTRAINT fk_material_owner FOREIGN KEY (owner_user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- Shared
-- ============================================================

CREATE TABLE notifications (
    notification_id      INT AUTO_INCREMENT PRIMARY KEY,
    user_id              INT NOT NULL,
    message              TEXT NOT NULL,
    type                 VARCHAR(20) NOT NULL,
    is_read              BOOLEAN NOT NULL DEFAULT FALSE,
    created_at           DATETIME NOT NULL,
    CONSTRAINT fk_notification_user FOREIGN KEY (user_id) REFERENCES users(user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;
